# AN-0001-07 step 3: assemble results.json (counts, probabilities, AI-proposed failure categories, contribution to the published review's analyses, sources).
# The failure categories and the contribution statements below were written by the AI assistant from the abstracts, the criteria and the
# published review text (PMC HTML, fetched 2026-09-26); they are AI-proposed and not yet verified by an author (same status as appendix section 7).
import json, os, time
OUT = os.path.dirname(os.path.abspath(__file__))
M = json.load(open(f'{OUT}/missed_studies.json')); R = json.load(open(f'{OUT}/review_parse.json'))
fetch = open(f'{OUT}/sources/fetch_log.txt').read().strip().splitlines()
SRC = {'CD012233': {'pmc': 'PMC6513652', 'pmid': '30109701', 'doi': '10.1002/14651858.CD012233.pub2'}, 'CD011977': {'pmc': 'PMC6494477', 'pmid': '29786830', 'doi': '10.1002/14651858.CD011977.pub2'}, 'CD010558': {'pmc': 'PMC6494651', 'pmid': '29761488', 'doi': '10.1002/14651858.CD010558.pub2'}}
CAT = {
 '9362194': {'category': 'E (proposed new category): CLEF content-level label does not correspond to an included study of the published review', 'basis': 'The published review (CD012233.pub2) cites Chen 1997 only under Additional references, as a background source for the prevalence of gallbladder polyps in Asian populations; it is not among the 16 included studies, it appears in none of the five data tables by test, and the abstract describes a prevalence and risk-factor survey without diagnostic accuracy data (no index test against a reference standard). A low probability is consistent with the written criteria.', 'contribution': 'None: not an included study of the published review; contributes to no data table, meta-analysis or summary of findings.', 'pooled_estimate_effect': 'Not applicable (no data in the review).'},
 '15682919': {'category': 'B: eligibility information not stated in the abstract (the abstract frames the trial as an aspheric versus spherical intraocular lens comparison; that the spherical comparator AcrySof Natural SN60AT is a blue-light filtering lens is product knowledge not stated in the abstract)', 'basis': 'Abstract: Tecnis Z9000 versus Sensar AR40e and AcrySof Natural SN60AT; contrast sensitivity and BCVA at six months. The review table of intraocular lenses lists Kennis 2004 with blue-light filtering IOL AcrySof Natural SN60AT and non-blue-light filtering IOL Tecnis Z9000 or Opti-Edge.', 'contribution': 'Primary outcome (distance BCVA at six to 18 months): the review states that six studies including Kennis 2004 reported relevant data, that Kennis 2004 could not be included in the meta-analysis because it analysed 98 eyes of 71 participants without details of the analysis approach, and that its findings were presented separately (Analysis 1.2, Figure 5). The pooled estimate (Analysis 1.1; MD -0.01 logMAR, 95% CI -0.03 to 0.02; 2 studies, 131 eyes) comprised Caporossi 2009 and Vuori 2006 only. Secondary outcome contrast sensitivity: listed as potentially relevant but no measures of variability, so no data were included.', 'pooled_estimate_effect': 'Removing Kennis 2004 would not change the pooled primary-outcome estimate, because it was not part of it. Whether the GRADE rating for this outcome took the separately presented Kennis 2004 result into account is not stated in the text and was not determined.'},
 '19781467': {'category': 'B: eligibility information not stated in the abstract (aspheric versus spherical comparison; the spherical group used AcrySof Natural SN60AT, a blue-light filtering lens, which the abstract does not state)', 'basis': 'Abstract: four IOL groups (AcrySof SN60WF, Tecnis ZA9003, Hoya PY-60AD, AcrySof Natural SN60AT); outcomes are higher-order aberrations and pupil diameter.', 'contribution': 'No data for the primary outcome or for any meta-analysis: the review mentions Yamaguchi 2009 only in the description of study designs and countries, in the risk-of-bias assessment, and in the adverse-effects summary (no participants developed intraoperative or postoperative complications).', 'pooled_estimate_effect': 'Not applicable (no pooled estimate uses this study).'},
 '19491981': {'category': 'B: eligibility information not stated in the abstract (aspheric versus spherical comparison; the spherical control AcrySof Natural is a blue-light filtering lens, which the abstract does not state)', 'basis': 'Abstract: AcrySof IQ SN60WF or Tecnis Z9001 versus AcrySof Natural; aberrations and contrast sensitivity up to two months. The review lists Cui 2009 with blue-light filtering IOL AcrySof Natural SN60AT or AcrySof IQ SN60WF and non-blue-light filtering IOL Tecnis Z9001.', 'contribution': 'No data for the primary outcome or for any meta-analysis: the review states that its distance BCVA data were not relevant to the primary outcome because follow-up was under six months and that the publication lacked quantitative data; Cui 2009 appears in the adverse-effects summary table (intraoperative complications: none) and in the risk-of-bias tables.', 'pooled_estimate_effect': 'Not applicable (no pooled estimate uses this study).'},
 '23851972': {'category': 'D (proposed new category): secondary report of an included study whose other reports were retrieved above tau', 'basis': 'The record is a mixed-methods study of patients\' experiences of taking part in the CoBalT trial; the review lists it as one of the reports of the included study Wiles 2016. Its abstract contains no information on the trial\'s eligibility-relevant design, population or outcomes. The five other CoBalT reports in the CLEF set (PMIDs 22101205, 23219570, 24262818, 24824481, 25527998) had Jev probabilities of 0.77 to 0.95.', 'contribution': 'The record itself contributes no outcome data; the trial (Wiles 2016) contributes to the primary outcomes through its main reports, which were above tau, so the trial would not have been lost.', 'pooled_estimate_effect': 'Not applicable (the record carries no outcome data; the study is retained through its other reports).'}}
out = {'analysis': 'AN-0001-07', 'compiled': time.strftime('%Y-%m-%d %H:%M:%S %Z'), 'tau': 0.07, 'status_of_categories': 'AI-proposed, not verified by an author (same status as appendix section 7); categories A, B, C as in appendix section 7; D and E are proposed additions.',
       'sources': {cd: {**SRC[cd], 'pmc_html_url': f'https://pmc.ncbi.nlm.nih.gov/articles/{SRC[cd]["pmc"]}/', 'fetch_log': [l for l in fetch if SRC[cd]['pmc'] in l], 'note': 'The PMC XML from E-utilities contains the abstract only (publisher restriction); the PMC HTML page contains the full review text including the reference list sections, the characteristics of included studies and the data tables. Cochrane Library and Wiley pages were not reachable from this server (HTTP 412 and 403).'} for cd in SRC},
       'criteria_source': {cd: {'pmid': M['reviews'][cd]['criteria_source_pmid'], 'year': M['reviews'][cd]['criteria_source_year']} for cd in SRC}, 'reviews': {}}
for cd in SRC:
    v = M['reviews'][cd]; P = R[cd]; v = dict(v, missed=P['missed'])
    inc_ids = set(P['included_study_ids']); rel = P['clef_relevant_pmids']
    by_sec = {}
    for p, d in rel.items():
        for h, s in d['found_in']: by_sec[h] = by_sec.get(h, 0) + 1
    # study-level recall among the published review's included studies represented in the CLEF relevant set
    sid_p = {}
    for p, d in rel.items():
        for h, s in d['found_in']:
            if h == 'References to studies included in this review': sid_p.setdefault(s, []).append(d['p'])
    n_sid = len(sid_p); n_sid_found = sum(1 for s, ps in sid_p.items() if max(ps) >= 0.07)
    out['reviews'][cd] = {'type': v['type'], 'N': v['N'], 'n_clef_content_relevant': v['n_included'], 'n_clef_abstract_relevant': v['n_ta_positive'], 'n_read_at_tau': v['n_read_at_tau'], 'work_at_tau': v['work_at_tau'], 'recall_at_tau_clef_content_labels': v['recall_at_tau'], 'n_relevant_below_tau': v['n_included_below_tau'], 'n_abstract_relevant_below_tau': v['n_ta_positive_below_tau'],
                          'largest_tau_keeping_95_recall': v['largest_tau_keeping_95_recall'], 'clef_relevant_p_sorted': v['included_p_sorted'],
                          'published_review': {'n_included_studies': len(inc_ids), 'clef_relevant_pmids_by_reference_list_section': by_sec, 'n_included_study_ids_represented_in_clef_relevant_set': n_sid, 'n_of_these_with_at_least_one_report_at_or_above_tau': n_sid_found, 'study_level_recall_at_tau': (n_sid_found / n_sid) if n_sid else None},
                          'missed': []}
    for m in v['missed']:
        c = CAT[m['pmid']]
        out['reviews'][cd]['missed'].append({'pmid': m['pmid'], 'first_author': m.get('first_author'), 'year': m.get('year'), 'journal': m.get('journal'), 'doi': m.get('doi'), 'title': m['title'], 'jev_probability': m['p'], 'rank': m['rank'], 'rank_proportion': m['rank_pct'], 'clef_abstract_label': m['label_ta'],
                                              'study_id_in_published_review': m.get('study_id'), 'reference_list_section': [h for h, s in m['reference_list_sections']], 'other_reports_of_same_study_in_clef_set': [x for x in (m.get('other_pmids_same_study') or []) if x['in_clef_set']],
                                              'ai_proposed_category': c['category'], 'basis': c['basis'], 'contribution_to_published_review': c['contribution'], 'effect_of_removal_on_pooled_estimate': c['pooled_estimate_effect'], 'n_mentions_in_review_text': m.get('n_review_text_mentions'), 'evidence_sentences': (m.get('review_text_mentions') or [])[:12]})
json.dump(out, open(f'{OUT}/results.json', 'w'), indent=1, ensure_ascii=False)
for cd, v in out['reviews'].items():
    print(cd, v['type'], 'N', v['N'], 'CLEF content-relevant', v['n_clef_content_relevant'], 'below tau', v['n_relevant_below_tau'], 'recall', round(v['recall_at_tau_clef_content_labels'], 4), 'work', round(v['work_at_tau'], 4), '| published review included', v['published_review']['n_included_studies'], 'sections', v['published_review']['clef_relevant_pmids_by_reference_list_section'], 'study-level recall', v['published_review']['study_level_recall_at_tau'])
    for m in v['missed']: print('   ', m['pmid'], m['jev_probability'], m['study_id_in_published_review'], m['reference_list_section'], '|', m['ai_proposed_category'][:60])
